fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since `a` and `b` are guaranteed to have the same length,
    // we can safely zip them together and compare element-wise.
    a.iter()
     .zip(b.iter())
     .map(|(x, y)| x <= y)
     .collect()
}

